Here's a thread-safe LRU cache with a custom doubly linked list:

```cpp
#include <unordered_map>
#include <mutex>
#include <optional>
#include <stdexcept>

template <typename Key, typename Value>
class LRUCache {
private:
    struct Node {
        Key key;
        Value value;
        Node* prev;
        Node* next;

        Node(const Key& k, const Value& v)
            : key(k), value(v), prev(nullptr), next(nullptr) {}
    };

    // Sentinel-based doubly linked list: head <-> ... <-> tail
    // Most-recently-used sits right after head; LRU sits right before tail.
    Node* head_;
    Node* tail_;
    std::unordered_map<Key, Node*> map_;
    size_t capacity_;
    mutable std::mutex mtx_;

    // ---- list helpers (must be called with mtx_ held) ----
    void detach(Node* node) noexcept {
        node->prev->next = node->next;
        node->next->prev = node->prev;
    }

    void push_front(Node* node) noexcept {
        node->prev = head_;
        node->next = head_->next;
        head_->next->prev = node;
        head_->next = node;
    }

    void move_to_front(Node* node) noexcept {
        detach(node);
        push_front(node);
    }

    Node* pop_back() noexcept {
        if (tail_->prev == head_) return nullptr; // empty
        Node* lru = tail_->prev;
        detach(lru);
        return lru;
    }

public:
    explicit LRUCache(size_t capacity) : capacity_(capacity) {
        if (capacity_ == 0) {
            throw std::invalid_argument("LRUCache capacity must be > 0");
        }
        head_ = new Node(Key{}, Value{});
        tail_ = new Node(Key{}, Value{});
        head_->next = tail_;
        tail_->prev = head_;
    }

    ~LRUCache() {
        std::lock_guard<std::mutex> lock(mtx_);
        Node* cur = head_;
        while (cur) {
            Node* next = cur->next;
            delete cur;
            cur = next;
        }
    }

    // Non-copyable, non-movable for simplicity (mutex isn't movable anyway).
    LRUCache(const LRUCache&) = delete;
    LRUCache& operator=(const LRUCache&) = delete;
    LRUCache(LRUCache&&) = delete;
    LRUCache& operator=(LRUCache&&) = delete;

    /// Returns the value associated with key, or std::nullopt if not present.
    /// Promotes the entry to most-recently-used on hit.
    std::optional<Value> get(const Key& key) {
        std::lock_guard<std::mutex> lock(mtx_);
        auto it = map_.find(key);
        if (it == map_.end()) return std::nullopt;

        move_to_front(it->second);
        return it->second->value;
    }

    /// Inserts or updates (key, value). Evicts LRU entry if over capacity.
    void put(const Key& key, const Value& value) {
        std::lock_guard<std::mutex> lock(mtx_);
        auto it = map_.find(key);
        if (it != map_.end()) {
            it->second->value = value;
            move_to_front(it->second);
            return;
        }

        if (map_.size() >= capacity_) {
            Node* lru = pop_back();
            if (lru) {
                map_.erase(lru->key);
                delete lru;
            }
        }

        Node* node = new Node(key, value);
        push_front(node);
        map_.emplace(key, node);
    }

    size_t size() const {
        std::lock_guard<std::mutex> lock(mtx_);
        return map_.size();
    }

    size_t capacity() const noexcept { return capacity_; }
};
```

### Quick demo

```cpp
#include <iostream>
#include <thread>
#include <vector>

int main() {
    LRUCache<int, std::string> cache(3);

    cache.put(1, "one");
    cache.put(2, "two");
    cache.put(3, "three");

    std::cout << *cache.get(1) << "\n";  // "one" -> 1 becomes MRU
    cache.put(4, "four");                // evicts key 2 (LRU)

    std::cout << (cache.get(2) ? "hit" : "miss") << "\n"; // miss
    std::cout << *cache.get(3) << "\n";                   // "three"

    // Concurrent stress
    std::vector<std::thread> threads;
    for (int t = 0; t < 8; ++t) {
        threads.emplace_back([&cache, t] {
            for (int i = 0; i < 1000; ++i) {
                cache.put(i % 10, "v" + std::to_string(t));
                cache.get(i % 10);
            }
        });
    }
    for (auto& th : threads) th.join();

    std::cout << "size=" << cache.size() << "\n";
}
```

### Design notes

- **Sentinel head/tail nodes** eliminate null checks in `detach`/`push_front`. This is the main source of bugs in hand-rolled LRU lists, so paying two extra nodes is worth it.
- **Hash map stores raw `Node*`**, giving O(1) lookup plus O(1) splice via the node's own pointers. No tree lookups, no list traversal.
- **Single `std::mutex`** protects both the map and the list. `get` mutates the list (moves to front), so a `shared_mutex` would degrade to exclusive locking anyway. Don't be tempted by `shared_mutex` here unless you split read-only "peek" semantics from the LRU update.
- **Lock scope** covers the whole operation, including the `delete` of the evicted node. That's fine because deletion is cheap; if `Value` had an expensive destructor you could move the node out under the lock and destroy it after release.
- **Exception safety**: `new Node(...)` could throw, but it happens before any list/map mutation, so the cache stays consistent. `map_.emplace` after `push_front` is the one ordering risk; if you want strict strong-exception-safety, reserve the map slot first or use `try_emplace` and roll back on failure.
- **Capacity 0** is rejected at construction; allowing it would mean every `put` immediately evicts itself, which is almost certainly a bug in caller code.

If you need higher concurrency, the standard next step is sharding: N independent `LRUCache` instances keyed by `hash(key) % N`, each with its own mutex. That scales near-linearly with cores for typical workloads.

Here's a clean implementation using preorder traversal with `#` as the null sentinel:

```rust
use std::cell::RefCell;
use std::rc::Rc;

type TreeNodeRef = Option<Rc<RefCell<TreeNode>>>;

#[derive(Debug, PartialEq)]
pub struct TreeNode {
    pub val: i32,
    pub left: TreeNodeRef,
    pub right: TreeNodeRef,
}

impl TreeNode {
    pub fn new(val: i32) -> Self {
        TreeNode { val, left: None, right: None }
    }
}

const NULL_SENTINEL: &str = "#";
const SEPARATOR: char = ',';

pub struct Codec;

impl Codec {
    pub fn new() -> Self {
        Codec
    }

    /// Serialize a tree to a string using preorder traversal.
    pub fn serialize(&self, root: &TreeNodeRef) -> String {
        let mut out = String::new();
        Self::serialize_inner(root, &mut out);
        out
    }

    fn serialize_inner(node: &TreeNodeRef, out: &mut String) {
        match node {
            None => {
                out.push_str(NULL_SENTINEL);
                out.push(SEPARATOR);
            }
            Some(n) => {
                let n = n.borrow();
                out.push_str(&n.val.to_string());
                out.push(SEPARATOR);
                Self::serialize_inner(&n.left, out);
                Self::serialize_inner(&n.right, out);
            }
        }
    }

    /// Deserialize a string back into a tree.
    pub fn deserialize(&self, data: &str) -> TreeNodeRef {
        let mut iter = data.split(SEPARATOR).filter(|s| !s.is_empty());
        Self::deserialize_inner(&mut iter)
    }

    fn deserialize_inner<'a, I>(iter: &mut I) -> TreeNodeRef
    where
        I: Iterator<Item = &'a str>,
    {
        let token = iter.next()?;
        if token == NULL_SENTINEL {
            return None;
        }
        let val: i32 = token.parse().ok()?;
        let node = Rc::new(RefCell::new(TreeNode::new(val)));
        node.borrow_mut().left = Self::deserialize_inner(iter);
        node.borrow_mut().right = Self::deserialize_inner(iter);
        Some(node)
    }
}

impl Default for Codec {
    fn default() -> Self {
        Self::new()
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    fn leaf(val: i32) -> TreeNodeRef {
        Some(Rc::new(RefCell::new(TreeNode::new(val))))
    }

    fn node(val: i32, left: TreeNodeRef, right: TreeNodeRef) -> TreeNodeRef {
        Some(Rc::new(RefCell::new(TreeNode { val, left, right })))
    }

    #[test]
    fn round_trip_basic() {
        // Tree:
        //       1
        //      / \
        //     2   3
        //        / \
        //       4   5
        let tree = node(1, leaf(2), node(3, leaf(4), leaf(5)));
        let codec = Codec::new();
        let s = codec.serialize(&tree);
        assert_eq!(s, "1,2,#,#,3,4,#,#,5,#,#,");
        let restored = codec.deserialize(&s);
        assert_eq!(codec.serialize(&restored), s);
    }

    #[test]
    fn round_trip_empty() {
        let codec = Codec::new();
        let tree: TreeNodeRef = None;
        let s = codec.serialize(&tree);
        assert_eq!(s, "#,");
        assert!(codec.deserialize(&s).is_none());
    }

    #[test]
    fn round_trip_single_node() {
        let codec = Codec::new();
        let tree = leaf(42);
        let s = codec.serialize(&tree);
        let restored = codec.deserialize(&s);
        assert_eq!(codec.serialize(&restored), s);
    }

    #[test]
    fn round_trip_negative_values() {
        let codec = Codec::new();
        let tree = node(-1, leaf(-2), node(-3, None, leaf(-4)));
        let s = codec.serialize(&tree);
        let restored = codec.deserialize(&s);
        assert_eq!(codec.serialize(&restored), s);
    }

    #[test]
    fn round_trip_left_skewed() {
        let codec = Codec::new();
        let tree = node(1, node(2, node(3, leaf(4), None), None), None);
        let s = codec.serialize(&tree);
        let restored = codec.deserialize(&s);
        assert_eq!(codec.serialize(&restored), s);
    }
}
```

### Design notes

- **Format**: preorder DFS, comma-separated tokens, `#` for null. So the tree `1 -> (2, 3 -> (4, 5))` serializes to `1,2,#,#,3,4,#,#,5,#,#,`.
- **Why preorder**: deserialization becomes a one-pass recursive consume of an iterator. Each call grabs the next token, and if it's a value, recursively builds left then right.
- **Sentinel choice**: `#` is unambiguous since values are `i32`. If you needed to support arbitrary strings as values, switch to a length-prefixed or escaped encoding.
- **Tree representation**: `Option<Rc<RefCell<TreeNode>>>` matches the shape used in LeetCode-style Rust problems. If your tree is owned (`Box<TreeNode>`) the same algorithm works with minor signature changes.
- **Complexity**: both operations are O(n) time and O(h) recursion depth. For very deep trees you'd want an iterative version to avoid stack overflow.

Run the tests with `cargo test` to verify the round-trip.

# Sliding Window Rate Limiter for Express

Here's a clean implementation using an in-memory store with a true sliding window algorithm (tracking individual request timestamps, not fixed buckets).

## Implementation

```javascript
// rateLimiter.js
'use strict';

/**
 * Sliding window rate limiter middleware factory.
 *
 * @param {Object} options
 * @param {number} [options.windowMs=1000] - Window size in milliseconds.
 * @param {number} [options.max=5]         - Max requests per IP per window.
 * @param {Function} [options.keyGenerator] - Custom key extractor (req) => string.
 * @returns {Function} Express middleware.
 */
function rateLimiter({
  windowMs = 1000,
  max = 5,
  keyGenerator = (req) => req.ip,
} = {}) {
  // Map<key, number[]> — timestamps (ms) of recent requests, oldest first.
  const hits = new Map();

  // Periodic cleanup so idle keys don't leak memory.
  const sweeper = setInterval(() => {
    const cutoff = Date.now() - windowMs;
    for (const [key, timestamps] of hits) {
      // Drop expired entries from the front.
      while (timestamps.length && timestamps[0] <= cutoff) {
        timestamps.shift();
      }
      if (timestamps.length === 0) hits.delete(key);
    }
  }, windowMs).unref?.(); // Don't block process exit.

  const middleware = (req, res, next) => {
    const key = keyGenerator(req);
    if (!key) return next(); // Fail open if no key.

    const now = Date.now();
    const cutoff = now - windowMs;

    let timestamps = hits.get(key);
    if (!timestamps) {
      timestamps = [];
      hits.set(key, timestamps);
    }

    // Evict timestamps outside the sliding window.
    while (timestamps.length && timestamps[0] <= cutoff) {
      timestamps.shift();
    }

    if (timestamps.length >= max) {
      const retryAfterMs = timestamps[0] + windowMs - now;
      const retryAfterSec = Math.max(1, Math.ceil(retryAfterMs / 1000));

      res.setHeader('X-RateLimit-Limit', max);
      res.setHeader('X-RateLimit-Remaining', 0);
      res.setHeader('X-RateLimit-Reset', Math.ceil((timestamps[0] + windowMs) / 1000));
      res.setHeader('Retry-After', retryAfterSec);

      return res.status(429).json({
        error: 'Too Many Requests',
        message: `Rate limit exceeded. Try again in ${retryAfterSec}s.`,
      });
    }

    // Record this request.
    timestamps.push(now);

    res.setHeader('X-RateLimit-Limit', max);
    res.setHeader('X-RateLimit-Remaining', max - timestamps.length);

    next();
  };

  // Expose the sweeper so tests can stop it.
  middleware.stop = () => clearInterval(sweeper);
  return middleware;
}

module.exports = rateLimiter;
```

## Usage

```javascript
// server.js
const express = require('express');
const rateLimiter = require('./rateLimiter');

const app = express();

// Required when behind a reverse proxy (nginx, ELB, etc.) so req.ip is correct.
app.set('trust proxy', 1);

// 5 requests per second per IP.
app.use(rateLimiter({ windowMs: 1000, max: 5 }));

app.get('/', (req, res) => res.json({ ok: true, ts: Date.now() }));

app.listen(3000, () => console.log('Listening on :3000'));
```

## How the algorithm works

For each IP, we keep an array of request timestamps. On every request:

1. Drop timestamps older than `now - windowMs` (slide the window forward).
2. If remaining count `>= max`, reject with **429** and set `Retry-After` based on when the oldest in-window request will expire.
3. Otherwise, append `now` and let the request through.

Unlike fixed-window counters, this prevents the classic burst problem where a client could fire `2 * max` requests across a window boundary.

## Things to know before production

- **In-memory only.** Counters reset on restart and don't sync across processes/instances. For multi-instance deployments, swap the `Map` for Redis using `ZADD`/`ZREMRANGEBYSCORE` on a sorted set keyed by IP — same algorithm, distributed state.
- **Memory cost.** O(max) timestamps per active key. With `max=5` this is trivial; if you raise `max` to thousands, consider a counter-based approximation (e.g., weighted sliding window).
- **`trust proxy`** must be configured correctly behind a load balancer, otherwise every request looks like it comes from the proxy IP and you'll rate-limit your whole user base together.
- **IPv6.** `req.ip` gives a single address; if you want to bucket by /64 prefix, do that in `keyGenerator`.

